css:
/* T3 Codex v0 draft. Refine against Codex app screenshots. */
:root {
  --t3x-font: ui-sans-serif, -apple-system, system-ui, "Segoe UI", Helvetica, Arial, sans-serif;
  --t3x-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
}
body, [data-slot="sidebar"], [data-workspace-area="conversation"], .composer-tiptap { font-family: var(--t3x-font) !important; }
code, pre, .chat-markdown-codeblock { font-family: var(--t3x-mono) !important; }

/* Sidebar rows: soft rounded pills */
[data-thread-item] { border-radius: 10px !important; }

/* User message: rounded grey bubble, right aligned */
[data-user-message-bubble] { border-radius: 18px !important; border: 0 !important; padding: 10px 16px !important; }

/* Assistant text: plain on canvas, comfortable line height */
.chat-markdown { line-height: 1.65 !important; }
.chat-markdown-codeblock { border-radius: 14px !important; }

/* Composer: big rounded card */
[data-slot="composer-host"] { border-radius: 28px !important; }
.dark [data-slot="composer-host"] { background: #303030 !important; border-color: transparent !important; box-shadow: none !important; }
:root:not(.dark) [data-slot="composer-host"] { background: #ffffff !important; border: 1px solid #e5e5e5 !important; box-shadow: 0 4px 16px rgba(0,0,0,0.05) !important; }

/* Popovers, menus, dialogs */
[data-slot="menu-popup"], [data-slot="popover-popup"] { border-radius: 16px !important; }
[data-slot="dialog-popup"] { border-radius: 20px !important; }
[data-slot="tooltip-popup"] { border-radius: 8px !important; }

/* Icons: slightly thinner strokes */
svg.lucide { stroke-width: 1.75; }

/* Scrollbars */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: rgba(127,127,127,0.25); border-radius: 8px; }
